def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    """
    Calculate the maximum sum of values collected on two paths in an N x N grid.
    Each cell's value can be collected at most once, even if both paths pass through it.
    """
    # Build grid with 1-indexed coordinates
    grid = [[0] * (N + 1) for _ in range(N + 1)]
    for x, y, val in grid_values:
        if x == 0 and y == 0 and val == 0:
            break
        if 1 <= x <= N and 1 <= y <= N:
            grid[x][y] = val

    # Edge case: single cell grid
    if N == 1:
        return grid[1][1]

    # Initialize DP arrays
    NEG_INF = -10**15
    dp_prev = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
    dp_prev[1][1] = grid[1][1]

    # Iterate over all possible sums of coordinates (k = i + j)
    for k in range(3, 2 * N + 1):
        dp_cur = [[NEG_INF] * (N + 1) for _ in range(N + 1)]
        # i1 and i2 range for current k
        i_min = max(1, k - N)
        i_max = min(N, k - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = k - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = k - i2
                if j2 < 1 or j2 > N:
                    continue
                # Compute best previous state
                best_prev = NEG_INF
                for di1 in (0, 1):
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        if pi1 < 1 or pi2 < 1:
                            continue
                        prev_val = dp_prev[pi1][pi2]
                        if prev_val > best_prev:
                            best_prev = prev_val
                if best_prev == NEG_INF:
                    continue
                # Add current cell values (avoid double counting)
                add = grid[i1][j1]
                if i1 != i2 or j1 != j2:
                    add += grid[i2][j2]
                dp_cur[i1][i2] = best_prev + add
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] != NEG_INF else 0

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and uses this
    mapping to decode a given encrypted message. If a contradiction is found during mapping
    construction, or not all letters are represented in the mapping, the function returns "Failed".

    Args:
    encoded (str): A string representing the encoded information.
    original (str): A string representing the original information corresponding to the encoded string.
    message (str): A string representing the encrypted message to be decoded.

    Returns:
    str: The decoded message if successful, or "Failed" if the decoding is not possible.
    """
    # The mapping must be bijective and cover all 26 uppercase letters
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    reverse_mapping = {}

    for e, o in zip(encoded, original):
        # Check forward mapping consistency
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

        # Check reverse mapping consistency
        if o in reverse_mapping:
            if reverse_mapping[o] != e:
                return "Failed"
        else:
            reverse_mapping[o] = e

    # Ensure all 26 uppercase letters are represented in the mapping
    alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    if set(mapping.keys()) != set(alphabet):
        return "Failed"

    # Decode the message
    decoded_chars = []
    for ch in message:
        if ch not in mapping:
            return "Failed"
        decoded_chars.append(mapping[ch])

    return "".join(decoded_chars)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine if a statement is about a day of the week
    def is_day_statement(stmt: str) -> bool:
        upper_stmt = stmt.upper()
        return any(day.upper() in upper_stmt for day in days_of_week)

    # Helper to evaluate truth of a statement given the scenario
    def evaluate(stmt: str) -> bool:
        stmt = stmt.strip()
        # Normalize punctuation
        if stmt.endswith('.'):
            stmt = stmt[:-1]
        # Handle "I am guilty." / "I am not guilty."
        if stmt.lower() == "i am guilty":
            return scenario == speaker
        if stmt.lower() == "i am not guilty":
            return scenario != speaker
        # Handle "X is guilty." / "X is not guilty."
        parts = stmt.split()
        if len(parts) >= 3 and parts[1].lower() == "is":
            target = parts[0]
            if parts[2].lower() == "guilty":
                return scenario == target
            if parts[2].lower() == "not" and len(parts) >= 4 and parts[3].lower() == "guilty":
                return scenario != target
        # If statement doesn't match known patterns, assume it's false (cannot be verified)
        return False

    for speaker, stmts in statements.items():
        # Determine if speaker is a liar
        is_liar = speaker in liar_count
        for stmt in stmts:
            if is_day_statement(stmt):
                continue  # ignore day-of-week statements
            truth = evaluate(stmt)
            # If speaker is liar, statement must be false; if not liar, statement must be true
            if is_liar and truth:
                return False
            if not is_liar and not truth:
                return False
    return True

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1  # peak counted twice
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
